('demo-container-restaurant-hub','[DEMO] Container Restaurant Hub','Container','Container Fabrication','Karen, Nairobi',null,7,'Corten, Reclaimed timber, Stainless prep','Cluster of three converted 40ft containers forming a casual dining hub.',array['https://images.unsplash.com/photo-1567521464027-f127ff144326?w=1600']::text[],false,false,4),
