('demo-industrial-tank-farm','[DEMO] Industrial Tank Farm','Other','Tanks & Vessels','Mombasa Port',null,5,'6mm mild steel, Epoxy coating, Bunded base','Three 20,000L diesel tanks with bunding and dispensing canopy for a logistics fleet.',array['https://images.unsplash.com/photo-1611288875785-f4196eebf516?w=1600']::text[],false,false,15),
('demo-highway-service-restrooms','[DEMO] Highway Service Restrooms','Container','Container Fabrication','Nakuru',null,4,'PVC plumbing, Ceramic tile','Eight ablution containers for a roadside service plaza.',array['https://images.unsplash.com/photo-1552321554-5fefe8c9ef14?w=1600']::text[],false,false,16),
('demo-ranch-worker-housing','[DEMO] Ranch Worker Housing','Cabin','Modular Cabins','Naivasha',null,9,'Steel frame, Insulated panels','Eight bunkhouse cabins for a horticulture estate.',array['https://images.unsplash.com/photo-1555854877-bab0e564b8d5?w=1600']::text[],false,false,17),
('20ft-sales-office','20FT Sales Office','Container','Container shop',null,null,3,'Cladding corten, Insulation rockwool, Siding industrial, Interior basic','A 20 ft container converted into a sales office.',array['https://razgnrakpthcdfwihamo.supabase.co/storage/v1/object/public/gallery-images/1777195209588-6hhaek6qshj.png']::text[],false,true,18),
('modular-site-office-complex','Modular Site Office Complex','Cabin','Cabins','Lekki, Nigeria',null,6,'Modular cabins, Decking','Cluster of 8 modular site offices linked by walkways for a major construction project.',array['https://razgnrakpthcdfwihamo.supabase.co/storage/v1/object/public/gallery-images/gallery-site-office.jpg']::text[],false,true,19),
('industrial-tank-farm','Industrial Tank Farm','Other','Tanks & Pressure Vessels','Port Harcourt, Nigeria',null,6,'Carbon steel, Epoxy lining','Six vertical storage tanks fabricated, pressure-tested and installed for a fuel distribution depot.',array['https://razgnrakpthcdfwihamo.supabase.co/storage/v1/object/public/gallery-images/gallery-tank-farm.jpg']::text[],false,true,20)
